Future<void> waitFor(bool Function() fn, String what) async {
  final deadline = DateTime.now().add(const Duration(seconds: 5));
  while (!fn()) {
    if (DateTime.now().isAfter(deadline)) {
      throw StateError('waitFor timed out: $what');
    }
    await Future<void>.delayed(const Duration(milliseconds: 5));
  }
}

Future<(eb.EventBusBroker, EventBusClient)> setupBus() async {
